# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

# Number of failures the player is allowed before losing.
MAX_FAILURES = 9


def _initial_state(word):
    """The initial state of the game as a dictionary."""
    return {
        'word': word,
        'guessed': set(),
        'remaining_guesses': MAX_FAILURES,
        'status': STATUS_ONGOING,
    }


def _apply_guess(state, char):
    """Pure state transition: new state = f(old state, event).

    A guess of a letter that appears in the word (and has not been
    guessed before) reveals it and costs nothing.  Any other guess
    (wrong letter, or a repeat of a correct one) is a failure and
    consumes one of the remaining guesses.  The game is lost when a
    failure is made with no guesses left, and won as soon as every
    letter of the word has been revealed.
    """
    new_state = dict(state)
    new_state['guessed'] = set(state['guessed'])

    if char in state['word'] and char not in state['guessed']:
        # A correct, new letter: reveal it, no cost.
        new_state['guessed'].add(char)
        if _masked_word(new_state) == state['word']:
            new_state['status'] = STATUS_WIN
    else:
        # A failure: wrong letter or a repeat of a correct one.
        new_state['remaining_guesses'] = state['remaining_guesses'] - 1
        if new_state['remaining_guesses'] < 0:
            new_state['status'] = STATUS_LOSE

    return new_state


def _masked_word(state):
    """The word with every unguessed letter replaced by an underscore."""
    return ''.join(
        char if char in state['guessed'] else '_'
        for char in state['word']
    )


class Hangman:
    def __init__(self, word):
        self.state = _initial_state(word)

    @property
    def remaining_guesses(self):
        return self.state['remaining_guesses']

    def guess(self, char):
        if self.state['status'] != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self.state = _apply_guess(self.state, char)

    def get_masked_word(self):
        return _masked_word(self.state)

    def get_status(self):
        return self.state['status']

